export const cx=(...names)=>names.filter(Boolean).join(' ');
export function buttonClassName(o={}){
return cx('cieo-ctl','cieo-btn',`cieo-btn--${o.variant??'secondary'}`,`cieo-btn--${o.size??'md'}`,o.tone&&o.tone!=='neutral'&&`cieo-btn--tone-${o.tone}`,o.shape==='pill'&&'cieo-btn--pill',o.iconOnly&&'cieo-btn--icon',o.block&&'cieo-btn--block',o.className);
}
